INSERT INTO verses (volume_id, book_id, chapter_id, verse_id, volume_title, book_title, chapter_number, verse_number, scripture_text) VALUES (1, 4, 124, 3871, 'Old Testament', 'Numbers', 7, 20, 'One spoon of gold of ten shekels, full of incense:');
